desserts:[["Brazilian Flan", "$10.95", "Silky egg custard with a golden caramel top. A Brazilian staple done the way it should be.", 0, "0f2ade5d-cd71-401e-9e81-91b7e7127070/flan.jpeg"], ["Creme Bruleé", "$10.95", "Creamy vanilla custard with a perfectly torched sugar crust. That crack never gets old.", 0, "dd7def8e-4cf8-476e-957b-a3748be277bd/creme+brulee.jpg"], ["Tres Leches Cake", "$11.95", "Sponge cake soaked in three milks until perfectly tender, finished with whipped cream. Pure comfort.", 0, "e7041828-40ee-4a1d-b021-c057e0673ec5/tres-leches-compressed.jpg"], ["Brasão Dessert Trio", "$13.95", "Can't pick just one? Get all three — Strawberry Cheesecake, Chocolate Mousse Cake, and Carrot Cake.", 0, "a65e48d1-147c-498c-b2f8-7858e9c64432/trio.jpg"], ["Papaya Cream", "$10.95", "Fresh papaya blended with vanilla ice cream. Add a splash of Crème de Cassis to take it up a notch.", 0, "5d9f758f-74bf-4caa-8b2d-7fc9857c8115/papaya7.jpg"], ["Strawberry Cheesecake", "$11.95", "New York-style cheesecake on a graham cracker crust, topped with fresh strawberries. A crowd pleaser.", 0, "3acb2900-af43-42f9-9017-e841cae8bd47/cheesecake.jpg"], ["Chocolate Molten Cake", "$11.95", "Warm chocolate cake with a molten center, served with vanilla bean ice cream. Order one for yourself.", 0, "366859a8-4c5f-442f-b4c7-84ecd846161f/molten.jpg"], ["Tiramisu", "$10.95", "Espresso-soaked ladyfingers layered with mascarpone cream and dusted with cocoa. Italy on a plate.", 0, "e86f9b78-671c-40a3-b16e-a20c47646d9a/tiramisu.jpg"], ["Chocolate Mousse Cake", "$11.95", "Moist chocolate cake layered with velvety mousse and finished with a ganache drizzle. For serious chocolate fans.", 0, "2568b64d-2ac1-4569-8b64-ee347a0e8887/mousse.jpg"], ["Carrot Cake", "$11.95", "Moist carrot cake with smooth cream cheese icing, served with a scoop of vanilla bean ice cream.", 0, "b2cc7d8c-b9d9-4e73-9e6c-11af56c4888b/carrot.jpg"], ["Key Lime Pie", "$11.95", "Tangy lime filling in a golden graham cracker crust, topped with whipped cream. Bright and refreshing.", 0, "07dfaa84-3f60-430b-a0f2-dbdd48eedb74/key+lime.jpg"], ["Flaming Cheesecake", "$16.95", "Cheesecake flambéed tableside with Licor 43 and caramelized brown sugar. A real showstopper.", 0, "62156815-011f-4596-aaec-3555ef7eea73/flaming+cheesecake.jpg"], ["Fresh Fruit Bowl", "$10.95", "A seasonal mix of fresh fruit topped with whipped cream. Light, fresh, and just right.", 0, "2cda8f30-c01d-4194-9e57-d326adbfe00c/fruit.jpg"], ["Ice Cream", "$10.95", "Classic vanilla ice cream made with real Madagascar beans. Simple, rich, and always satisfying.", 0, "5b4623fb-895a-48f6-b2b0-bda95121a7fa/+ice_cream.jpg"]],
