  var tk=false;window.addEventListener('scroll',function(){if(!tk){tk=true;requestAnimationFrame(function(){tk=false;stick();});}},{passive:true});
  window.addEventListener('resize',stick);window.addEventListener('load',stick);stick();setTimeout(stick,600);

