  function grid(a,o){var h=a.map(function(x){return item(x,o)}).join('');var pics=a.some(function(x){return x[4]});return h?'<div class="b-grid'+(pics?' pics':'')+'">'+h+'</div>':''}
  function sec(title,inner,count){if(!inner)return '';return '<section class="b-sec"><div class="b-sh"><h2>'+e(title)+'</h2>'+(count!=null?'<span>'+count+' selections</span>':'')+'</div>'+inner+'</section>'}
